def handle_call_tool(params, tool_registry: OrderedDict[str, tools.Tool]):
    """
    Handles the tools/call request from the client.
    """
    call_params = types.CallToolRequestParams.model_validate(params)
    tool_name = call_params.name
    arguments = call_params.arguments or {}

    if tool_name not in tool_registry:
        # TODO: Figure out how to return a proper JSON-RPC error
        # For now, return a result with an error indication.
        error_content = types.TextContent(text=f"Tool '{tool_name}' not found.")
        result = types.CallToolResult(content=[error_content], isError=True)
        return result.model_dump(exclude_none=True, by_alias=True)

    tool_info = tool_registry[tool_name]
    fn = tool_info.get('fn')

    if not fn:
        error_content = types.TextContent(
            text=f"Tool '{tool_name}' has no associated function."
        )
        result = types.CallToolResult(content=[error_content], isError=True)
        return result.model_dump(exclude_none=True, by_alias=True)

    try:
        return _get_result(fn, arguments)
    except Exception as e:
        error_content = types.TextContent(text=f"Error calling tool '{tool_name}': {e}")
        result = types.CallToolResult(content=[error_content], isError=True)
        return result.model_dump(exclude_none=True, by_alias=True)


def _get_result(fn, arguments):
    # TODO: check if tool_result is list of content blocks, if so, return it as is

    tool_result = fn(**arguments)
    content = types.TextContent(text='')
    if isinstance(tool_result, str):
        content.text = tool_result

    structured = None
    try:
        content.text = content.text or json.dumps(tool_result)
        if isinstance(tool_result, dict):
            structured = tool_result
    except Exception:
        content.text = content.text or str(tool_result)

    result = types.CallToolResult(
        content=[content], structuredContent=structured, isError=False
    )

    return result.model_dump(exclude_none=True, by_alias=True)


def handle_list_tools(params, tool_registry: OrderedDict[str, tools.Tool]):
    """
    Handles the tools/list request from the client.
    https://modelcontextprotocol.io/specification/2025-06-18/tools/list#toolslist
    """
    # TODO: add pagination support
    types.ListToolsRequestParams.model_validate(params)

    tool_list = []
    for tool_info in tool_registry.values():
        if tool := get_validated_tool(tool_info):
            tool_list.append(tool)

    result = types.ListToolsResult(tools=tool_list, nextCursor=None)
    return result.model_dump(exclude_none=True, by_alias=True)


def get_validated_tool(tool: tools.Tool):
    t = {
        'name': tool.get('name'),
        'description': tool.get('description'),
        'inputSchema': tool.get('input_schema'),
        'outputSchema': tool.get('output_schema'),
        'annotations': tool.get('annotations'),
    }

    if t['outputSchema'] is None:
        del t['outputSchema']
    if t['annotations'] is None:
        del t['annotations']

    try:
        return types.Tool.model_validate(t)
    except ValidationError as e:
        print(e)
    return None


def safe_dumps(data: Any) -> str:
    try:
        return json.dumps(data)
    except Exception:
        return str(data)

import inspect
import re
import types
from collections.abc import Callable
from typing import (
    Any,
    Optional,
    Union,
    get_args,
    get_origin,
    get_type_hints,
)

# Mapping of Python types to JSON schema types
_PY_TO_JSON_TYPE_MAP = {
    int: 'integer',
    str: 'string',
    float: 'number',
    bool: 'boolean',
    type(None): 'null',
}


def _convert_py_to_json_type(py_type: Any) -> dict:
    """Convert a Python type to a JSON schema type dictionary."""
    if py_type in _PY_TO_JSON_TYPE_MAP:
        return {'type': _PY_TO_JSON_TYPE_MAP[py_type]}
    return {}


def _handle_union_type(py_type: Any) -> dict:
    """Handle Union and Optional types."""
    args = get_args(py_type)
    # Optional[T] is an alias for Union[T, None].
    is_optional = any(arg is type(None) for arg in args)

    # Filter out NoneType for processing
    non_none_args = [arg for arg in args if arg is not type(None)]

    if is_optional and len(non_none_args) == 1:
        # Handles Optional[T]
        schema = _convert_type_to_json_schema(non_none_args[0])
        # Add null type for optionality
        if 'type' in schema:
            if isinstance(schema['type'], list):
                if 'null' not in schema['type']:
                    schema['type'].append('null')
            else:
                schema['type'] = [schema['type'], 'null']
        else:
            # For complex types in Optional, wrap with anyOf
            return {'anyOf': [_convert_type_to_json_schema(arg) for arg in args]}
        return schema

    # Handles Union[T1, T2, ...]
    return {'anyOf': [_convert_type_to_json_schema(arg) for arg in args]}


def _handle_list_type(py_type: Any) -> dict:
    """Handle list types."""
    args = get_args(py_type)
    if args:
        # Handles list[T]
        return {'type': 'array', 'items': _convert_type_to_json_schema(args[0])}
    # Handles list
    return {'type': 'array'}


def _handle_dict_type(py_type: Any) -> dict:
    """Handle dict types."""
    args = get_args(py_type)
    if args and len(args) == 2:
        # Handles dict[K, V], assuming K is str
        return {
            'type': 'object',
            'additionalProperties': _convert_type_to_json_schema(args[1]),
        }
    # Handles dict
    return {'type': 'object'}


def _convert_type_to_json_schema(py_type: Any) -> dict:
    """Converts a Python type annotation to a JSON schema dictionary."""

    if py_type is list:
        return {'type': 'array'}
    if py_type is dict:
        return {'type': 'object'}

    # Handles simple types
    schema = _convert_py_to_json_type(py_type)
    if schema:
        return schema

    origin = get_origin(py_type)

    if origin in (Union, Optional, types.UnionType):
        # Handles Union and Optional types
        return _handle_union_type(py_type)

    if origin in (list, list):
        # Handles list types
        return _handle_list_type(py_type)

    if origin in (dict, dict):
        # Handles dict types
        return _handle_dict_type(py_type)

    if py_type is Any:
        # Handles Any type
        return {}

    # Fallback for unsupported types
    return {}


def get_input_schema(fn: Callable) -> dict:
    """
    Generate a JSON schema for a function's parameters.
    This function inspects the signature of `fn` and generates a JSON schema
    that describes the arguments, including their types and whether they are
    required.
    It supports standard Python types, as well as `Optional`, `Union`, `list`,
    and `dict` from the `typing` module.

    Example output:
    """
    try:
        # Resolve forward-referenced type hints
        type_hints = get_type_hints(fn)
    except (NameError, TypeError):
        # Fallback for unresolvable type hints
        type_hints = {}

    sig = inspect.signature(fn)
    parameters = sig.parameters
    input_schema = {
        'type': 'object',
        'properties': {},
    }

    if not parameters:
        return input_schema

    required_params = []

    for name, param in parameters.items():
        if param.kind not in (
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.KEYWORD_ONLY,
        ):
            continue

        annotation = type_hints.get(name, Any)

        # Convert Python type to a JSON schema property
        prop_schema = _convert_type_to_json_schema(annotation)

        input_schema['properties'][name] = prop_schema

        # Determine if the parameter is required
        if param.default is inspect.Parameter.empty:
            required_params.append(name)

    if required_params:
        input_schema['required'] = required_params

    return input_schema


def get_descriptions(desc: str) -> tuple[str, dict[str, str]]:
    """
    Parses a Google-style docstring to extract the function description and
    parameter descriptions.

    Args:
        desc (str): The docstring to parse.

    Returns:
        A tuple containing:
            - str: The function's description.
            - dict: A dictionary of parameter descriptions, with parameter
              names as keys.
    """
    if not desc:
        return '', {}

    desc = inspect.cleandoc(desc)

    try:
        description_part, args_part = re.split(r'\n\s*Args:\n', desc, maxsplit=1)
    except ValueError:
        if desc.lstrip().startswith('Args:'):
            description_part = ''
            args_part = desc.lstrip()[len('Args:') :].lstrip()
        else:
            return desc, {}

    arg_pattern = re.compile(
        r'^\s*(\w+)\s*(?:\([^)]*\))?:\s*(.*?)(?=\n\s*\w+\s*(?:\(.*\))?:|\Z)',
        re.MULTILINE | re.DOTALL,
    )
    arg_descriptions = {}
    for match in arg_pattern.finditer(args_part):
        arg_name, description = match.groups()
        arg_descriptions[arg_name] = ' '.join(description.strip().split())

    return description_part.strip(), arg_descriptions
